package pfm.android;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import android.content.Context;

public class QualifyingHarness {
    static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
    static HashMap<String,String> countries(NativeCareerStore.Career c){HashMap<String,String> out=new HashMap<>();for(NativeCareerStore.Club club:c.clubs)out.put(club.id,club.league);return out;}
    static void entries(MatchJournal plan,NativeCareerStore.Career career){
        Set<String> candidates=EuropeanQualification.candidates(plan),direct=new HashSet<>(EuropeanQualification.ids(plan.metadata("uclq-direct"))),base=new HashSet<>(EuropeanQualification.ids(plan.metadata("uelq-base")));ArrayList<String[]> pairs=EuropeanQualification.pairs(plan);check(candidates.size()==42&&direct.size()==22&&pairs.size()==10&&base.size()==38,"entry counts");for(String id:base)check(!candidates.contains(id),"Europa base overlaps UCL entries");HashMap<String,String> country=countries(career);HashSet<String> unique=new HashSet<>(direct);for(String[] pair:pairs){check(unique.add(pair[0])&&unique.add(pair[1]),"duplicate playoff club");check(!country.get(pair[0]).equals(country.get(pair[1])),"same-association playoff");}
        for(String code:NativeWorldCenter.C){int directCount=0,all=0,europa=0;for(String id:direct)if(id.startsWith(code+":"))directCount++;for(String id:candidates)if(id.startsWith(code+":"))all++;for(String id:base)if(id.startsWith(code+":"))europa++;check(directCount==EuropeanPlaces.champions(code)-1&&all==EuropeanPlaces.champions(code)&&europa==3,"top-five route counts "+code);}
    }
    static void selection(String world,File root)throws Exception{
        JournalHarness.world(world,940);NativeCareerStore.Career career=NativeCareerStore.current;MatchJournal previous=new MatchJournal(root,940,2010);for(String code:NativeWorldCenter.C)for(NativeWorldCenter.M fixture:NativeWorldCenter.schedule(NativeWorldCenter.leagues.get(code).size())){MatchJournal.Match m=new MatchJournal.Match();m.competition="league:"+code;m.round=fixture.r;m.home=code+":"+fixture.h;m.away=code+":"+fixture.a;m.homeGoals=1;m.id=NativeMatchJournal.key(m.competition,m.round,m.home,m.away);previous.put(m);}
        String holder=UclSeason.standings(previous,"en",career.clubs).get(19).id;MatchJournal.Match cup=new MatchJournal.Match();cup.id="holder";cup.competition="ucl:2010";cup.round=13;cup.home=holder;cup.away="es:0";cup.winner=holder;previous.put(cup);
        for(int seed=0;seed<100;seed++){MatchJournal next=new MatchJournal(root,1000+seed,2011);EuropeanQualification.prepare(next,previous,career,seed);entries(next,career);check(EuropeanQualification.ids(next.metadata("uclq-direct")).contains(holder),"holder not direct");String frozen=next.metadata("uclq-pairs"),base=next.metadata("uelq-base");EuropeanQualification.prepare(next,previous,career,seed+99);check(frozen.equals(next.metadata("uclq-pairs"))&&base.equals(next.metadata("uelq-base")),"entry redraw");check(next.metadata("ucl-groups")==null&&next.metadata("uel-groups")==null,"groups drawn before playoffs");}
        MatchJournal foreignPrevious=new MatchJournal(root,1300,2010);for(MatchJournal.Match m:previous.all())if(m.competition.startsWith("league:"))foreignPrevious.put(m);MatchJournal.Match foreignCup=new MatchJournal.Match();foreignCup.id="foreign-holder";foreignCup.competition="ucl:2010";foreignCup.round=13;foreignCup.home="eu_ireland:0";foreignCup.away="en:0";foreignCup.winner=foreignCup.home;foreignPrevious.put(foreignCup);MatchJournal foreignNext=new MatchJournal(root,1300,2011);EuropeanQualification.prepare(foreignNext,foreignPrevious,career,1300);entries(foreignNext,career);check(EuropeanQualification.ids(foreignNext.metadata("uclq-direct")).contains(foreignCup.winner),"external titleholder not direct");
        System.out.println("Selection: 100 frozen plans, 22 direct + 20 qualifying + 38 Europa base; top-five table routes, domestic/external titleholders and country restrictions verified");
    }
    static void destinations(Context context,MatchJournal journal)throws Exception{
        Set<String> cl=EuropaSeason.entrants(NativeMatchJournal.uclGroups(context,journal.season())),el=EuropaSeason.entrants(NativeMatchJournal.europaGroups(context,journal.season()));check(cl.size()==32&&el.size()==48,"final group sizes");for(String id:cl)check(!el.contains(id),"club in both group stages");for(String id:EuropeanQualification.ids(journal.metadata("uclq-direct")))check(cl.contains(id),"direct club lost place");HashSet<String> losers=new HashSet<>();for(String[] pair:EuropeanQualification.pairs(journal)){MatchJournal.Match first=journal.get(UclKnockout.key("uclq:"+journal.season(),1,pair[0],pair[1])),second=journal.get(UclKnockout.key("uclq:"+journal.season(),2,pair[1],pair[0]));check(first!=null&&second!=null&&second.winner.length()>0,"unresolved tie");String loser=second.winner.equals(pair[0])?pair[1]:pair[0];check(cl.contains(second.winner)&&el.contains(loser)&&!cl.contains(loser),"wrong winner / loser destination");losers.add(loser);int decision=UclKnockout.decision(first.homeGoals,first.awayGoals,second.homeGoals,second.awayGoals);if(second.homePenalties+second.awayPenalties==0)check(second.winner.equals(decision>0?second.home:second.away),"aggregate/away-goal winner mismatch");}
        check(losers.equals(new HashSet<>(EuropeanQualification.ids(journal.metadata("uel-from-uclq")))),"loser snapshot mismatch");
    }
    public static void main(String[] args)throws Exception{
        File root=new File(args[1]);root.mkdirs();selection(args[0],new File(root,"selection"));MatchJournal previous=null;
        for(String active:new String[]{"en","de"}){int nonce=active.equals("en")?941:942;File dir=new File(root,active);dir.mkdirs();Context context=new Context("overrides/app/src/main/assets",dir);AndroidRuntime.current=context;JournalHarness.world(args[0],nonce);NativeCareerStore.current.activeLeague=active;int total=active.equals("de")?34:38;for(int step=1;step<=total;step++){NativeWorldCenter.played=step;NativeMatchJournal.advance(context,step);}previous=JournalHarness.open(context,nonce,2010);MatchJournal next=JournalHarness.open(context,nonce,2011);entries(next,NativeCareerStore.current);String frozen=next.metadata("uclq-pairs");NativeWorldCenter.year=2011;NativeWorldCenter.played=0;NativeMatchJournal.advance(context,0);check(NativeMatchJournal.uclGroups(context,2011).isEmpty()&&NativeMatchJournal.europaGroups(context,2011).isEmpty(),"early groups");
            NativeWorldCenter.played=1;NativeMatchJournal.advance(context,1);next=JournalHarness.open(context,nonce,2011);check(next.competition("uclq:2011").size()==10&&next.competition("ucl:2011").isEmpty(),"first-leg calendar");HashMap<String,String> prefix=new HashMap<>();for(MatchJournal.Match m:next.all())prefix.put(m.id,JournalHarness.frozen(m));JournalHarness.restart();NativeMatchJournal.advance(context,1);next=JournalHarness.open(context,nonce,2011);for(Map.Entry<String,String> e:prefix.entrySet())check(e.getValue().equals(JournalHarness.frozen(next.get(e.getKey()))),"restart rewrote first leg");check(frozen.equals(next.metadata("uclq-pairs")),"restart changed draw");
            NativeWorldCenter.played=2;NativeMatchJournal.advance(context,2);next=JournalHarness.open(context,nonce,2011);check(next.competition("uclq:2011").size()==20,"second-leg calendar");destinations(context,next);for(Map.Entry<String,String> e:prefix.entrySet())check(e.getValue().equals(JournalHarness.frozen(next.get(e.getKey()))),"return legs rewrote prefix");for(MatchJournal.Match m:next.competition("uclq:2011")){check(m.effectsVersion>0,"live qualifier missing consequences");int hg=0,ag=0,hs=0,as=0;for(MatchJournal.PlayerFact p:m.players){if(p.club.equals(m.home)){hg+=p.stats[0];if(p.minutes>0&&p.stats[3]==0)hs++;}else{ag+=p.stats[0];if(p.minutes>0&&p.stats[3]==0)as++;}check(p.minutes<=m.duration,"qualifying minutes overflow");}check(hg==m.homeGoals&&ag==m.awayGoals&&hs<=3&&as<=3,"qualifying goal/substitution facts");}
            byte[] bytes=Files.readAllBytes(new File(dir,"match-journals/matches-"+nonce+"-2011.bin").toPath());NativeMatchJournal.qualifyingPairs(context,2011);NativeMatchJournal.qualifyingMatches(context,2011);NativeMatchJournal.uclCandidates(context,2011);check(Arrays.equals(bytes,Files.readAllBytes(new File(dir,"match-journals/matches-"+nonce+"-2011.bin").toPath())),"qualifying view changed save");for(int step=3;step<=total;step++){NativeWorldCenter.played=step;NativeMatchJournal.advance(context,step);}next=JournalHarness.open(context,nonce,2011);check(next.size()==2269&&next.competition("ucl:2011").size()==125&&next.competition("uel:2011").size()==205,"qualified season incomplete");
            System.out.println("Calendar "+active+": round-1/2 qualifiers, immutable first legs, exact winner/loser routing, 32/48 group entries and full 145 UCL + 205 Europa fixtures verified");}
        File dir=new File(root,"legacy");dir.mkdirs();Context context=new Context("overrides/app/src/main/assets",dir);AndroidRuntime.current=context;JournalHarness.world(args[0],943);MatchJournal old=JournalHarness.open(context,943,2011);ArrayList<ArrayList<String>> frozen=UclSeason.prepare(old,previous,NativeCareerStore.current,101);EuropaSeason.prepare(old,previous,NativeCareerStore.current,frozen,102);String cl=old.metadata("ucl-groups"),el=old.metadata("uel-groups");old.save();NativeWorldCenter.year=2011;NativeWorldCenter.played=2;JournalHarness.restart();NativeMatchJournal.advance(context,2);old=JournalHarness.open(context,943,2011);check(cl.equals(old.metadata("ucl-groups"))&&el.equals(old.metadata("uel-groups"))&&!EuropeanQualification.planned(old)&&old.competition("uclq:2011").isEmpty(),"v93 frozen tournament requalified");
        MatchEffects effects=new MatchEffects();effects.discipline("uclq:2011","uid").ban=1;check(!effects.available("uid","ucl:2011")&&!effects.available("uid","uel:2011")&&effects.available("uid","league:en"),"qualifier suspension scope");
        System.out.println("PASS: v93 frozen groups are preserved without retroactive qualifiers; qualifying cards share European discipline and stay separate from domestic bans");
    }
}
